package ir.sinicable.rubikaqueue;
import org.json.*;
import java.io.*;
import java.util.zip.*;
import java.nio.charset.StandardCharsets;
public final class ResearchXlsx {
 static String xml(String s){StringBuilder b=new StringBuilder();for(char c:s.toCharArray())if(c>=32||c=='\n'||c=='\r'||c=='\t')b.append(c);return b.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String col(int n){StringBuilder b=new StringBuilder();do{b.insert(0,(char)('A'+n%26));n=n/26-1;}while(n>=0);return b.toString();}
 static void entry(ZipOutputStream z,String path,String body)throws IOException{z.putNextEntry(new ZipEntry(path));z.write(body.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 static String sheet(JSONArray rows,String[] headers,String[] keys)throws Exception {
  StringBuilder s=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\" rightToLeft=\"1\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>");
  for(int i=0;i<headers.length;i++){int width=(keys[i].equals("excerpt")||keys[i].equals("source")||keys[i].equals("link")||keys[i].equals("status"))?55:(keys[i].equals("phone")?22:32);s.append("<col min=\"").append(i+1).append("\" max=\"").append(i+1).append("\" width=\"").append(width).append("\" customWidth=\"1\"/>");}
  s.append("</cols><sheetData>");
  for(int r=0;r<=rows.length();r++){s.append("<row r=\"").append(r+1).append("\" ht=\"").append(r==0?32:48).append("\" customHeight=\"1\">");for(int c=0;c<headers.length;c++){String text=r==0?headers[c]:rows.getJSONObject(r-1).optString(keys[c],"");if(text.length()>30000)text=text.substring(0,30000);s.append("<c r=\"").append(col(c)).append(r+1).append("\" t=\"inlineStr\" s=\"").append(r==0?1:2).append("\"><is><t xml:space=\"preserve\">").append(xml(text)).append("</t></is></c>");}s.append("</row>");}
  s.append("</sheetData><autoFilter ref=\"A1:").append(col(headers.length-1)).append(rows.length()+1).append("\"/></worksheet>");return s.toString();
 }
 public static void write(JSONObject data,OutputStream output)throws Exception {
  try(ZipOutputStream z=new ZipOutputStream(output)){
   entry(z,"[Content_Types].xml","<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet3.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
   entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
   entry(z,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"تماس‌های کاری عمومی\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"گروه‌ها\" sheetId=\"2\" r:id=\"rId2\"/><sheet name=\"گزارش جست‌وجو\" sheetId=\"3\" r:id=\"rId3\"/></sheets></workbook>");
   entry(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet3.xml\"/><Relationship Id=\"rId4\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
   entry(z,"xl/styles.xml","<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Tahoma\"/></font><font><b/><sz val=\"11\"/><color rgb=\"FFFFFFFF\"/><name val=\"Tahoma\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF086C66\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"3\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/><xf numFmtId=\"49\" fontId=\"1\" fillId=\"2\" borderId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"center\" horizontal=\"right\"/></xf><xf numFmtId=\"49\" fontId=\"0\" fillId=\"0\" borderId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"top\" horizontal=\"right\"/></xf></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");
   entry(z,"xl/worksheets/sheet1.xml",sheet(data.getJSONArray("contacts"),new String[]{"phone","name","موضوع","منبع عمومی","متن کنار شماره","نوع اطلاعات","اولین مشاهده UTC","آخرین مشاهده UTC"},new String[]{"phone","name","keyword","source","excerpt","visibility","first_seen","last_seen"}));
   entry(z,"xl/worksheets/sheet2.xml",sheet(data.getJSONArray("groups"),new String[]{"نام گروه","لینک","شناسه گروه","دسترسی","منبع","موضوع","وضعیت بررسی","اولین مشاهده UTC","آخرین مشاهده UTC"},new String[]{"name","link","guid","visibility","source","keyword","availability","first_seen","last_seen"}));
   entry(z,"xl/worksheets/sheet3.xml",sheet(data.getJSONArray("logs"),new String[]{"زمان UTC","منبع / عبارت","وضعیت"},new String[]{"time","source","status"}));
  }
 }
}
